<?php
namespace App\Services\HR; use App\Models\Appraisal;
class AppraisalScoreService {public function refresh(Appraisal $a):Appraisal{$a->loadMissing('kras.kpis');$req=$done=0;$weighted=$weight=0.0;foreach($a->kras as $kra){$req++;if($kra->title&&$kra->weight>0)$done++;foreach($kra->kpis as $k){$req++;if($k->title&&$k->target!==null&&$k->actual_achievement!==null)$done++;if($k->agreed_score!==null){$w=(float)$k->weight;$weighted+=((float)$k->agreed_score/5)*$w;$weight+=$w;}}}$a->update(['completion_percent'=>$req?round($done/$req*100,2):0,'performance_percent'=>$weight?round($weighted/$weight*100,2):null,'final_score'=>$weight?round($weighted/$weight*100,2):null]);return $a->fresh();} public function weightErrors(Appraisal $a):array{$a->loadMissing('kras.kpis');$e=[];$kt=round((float)$a->kras->sum('weight'),2);if($a->kras->isNotEmpty()&&abs($kt-100)>.01)$e[]="KRA weights total {$kt}%; they must total 100%.";foreach($a->kras as $kra){if($kra->kpis->isEmpty())continue;$t=round((float)$kra->kpis->sum('weight'),2);if(abs($t-100)>.01)$e[]="KPI weights for '{$kra->title}' total {$t}%; they must total 100%.";}return $e;}}
